using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Text.RegularExpressions;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 [Serializable]public sealed class AuditText {public string path,text;public bool bound;}
 [Serializable]public sealed class AuditPage {public string language,route;public AuditText[] texts;public string[] smallButtons;}
 [Serializable]public sealed class AuditItemArt {public string id,sprite,texture;public bool present;}
 [Serializable]public sealed class PresentationAudit {public string sourceCommit=Environment.GetEnvironmentVariable("IDLE_AUDIT_SOURCE")??"working tree (not a player build)";public bool prepared=true,cloudClientPresent,cloudConfigured,cloudSession;public AuditItemArt[] items;public AuditPage[] pages;}
 public sealed class PresentationAuditTests {
  const string Output="/tmp/idle-presentation-audit";GameRuntime game;string directory;readonly List<AuditPage> pages=new List<AuditPage>();PresentationAudit result;
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"idle-presentation-audit-"+Guid.NewGuid());Directory.CreateDirectory(directory);Directory.CreateDirectory(Output);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.tutorial="skipped";n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Tutorial="done";n.Settings.sfxMuted=true;n.Settings.musicEnabled=false;return n;});result=new PresentationAudit();var api=UnityEngine.Object.FindFirstObjectByType<CompanyApiClient>();result.cloudClientPresent=api!=null;result.cloudConfigured=api!=null&&api.IsConfigured;result.cloudSession=api!=null&&api.HasSession;Debug.Log("ISOLATED_PRESENTATION_AUDIT: temporary prepared save, no normal save or online login used");}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  void Prepare(){game.Act(s=>{var n=s.Copy();n.Credits=n.Data=ScientificNumber.From(1e20);n.Retention.aiName="AURA";n.Quality=10;n.Efficiency=8;n.Hardware[0]=25;n.Hardware[1]=10;n.Hardware[2]=2;n.Prestige.resets=1;n.Prestige.Total=n.Prestige.Free=n.Prestige.Cycle=n.Prestige.Entitlement=ScientificNumber.From(1e7);n.Prestige.known=PrestigeBalance.Nodes.Select(d=>d.Id).ToArray();n.Workshop.nodes=(string[])n.Prestige.known.Clone();n.Prestige.lab=n.Prestige.labSeed=true;n.Meta.resets=1;n.Meta.models=Enumerable.Repeat(0,MetaBalance.Models.Length).ToArray();n.Meta.available=n.Meta.total=ScientificNumber.From(10000).ToData();n.Meta.axioms=Enumerable.Repeat(1,MetaBalance.Axioms.Length).ToArray();n.Prestige.knowledge=ScientificNumber.From(10000).ToData();for(int i=0;i<n.Research.Length;i++)n.Research[i]=Balance.Research[i].Project?1:4;n.Workshop.learned=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.knownBlueprints=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.components=Enumerable.Repeat(100000L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.fragments=1000;n.Workshop.inventory=ItemBalance.Items.Select((d,i)=>new ItemInstance{id="audit-item-"+i,type=d.Id,level=12,rarity=i%6}).ToArray();var used=new List<string>();for(int slot=0;slot<6;slot++){string family=ItemBalance.Slots[slot].Replace("Aux","");var item=n.Workshop.inventory.First(i=>Workshop.Definition(i).Family==family&&!used.Contains(i.id));n=Workshop.Equip(n,item.id,ItemBalance.Slots[slot]);used.Add(item.id);}return MetaRules.Select(n,"K01");});game.Act(s=>{var n=s.Copy();n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.tutorial="skipped";return n;});game.Act(s=>Game.Research(s,"dataGeneration"));Assert.That(game.State.Story.open,Is.Null,"Prepared views must not accidentally resume the name introduction");}
  string PathFor(Transform t){var names=new List<string>();while(t!=null&&t!=game.transform){names.Add(t.name+"["+t.GetSiblingIndex()+"]");t=t.parent;}names.Reverse();return string.Join("/",names);}
  IEnumerator Record(string language,string route,bool capture=true){yield return null;yield return null;yield return new WaitForSecondsRealtime(.12f);game.FlushLocalization();foreach(var label in game.Content.GetComponentInParent<Canvas>().GetComponentsInChildren<UiLocalizedText>())label.RefreshNow();Canvas.ForceUpdateCanvases();Assert.That(game.Writable,Is.True,game.Status.text);var texts=game.Content.GetComponentInParent<Canvas>().GetComponentsInChildren<Text>().Where(t=>t.isActiveAndEnabled&&!string.IsNullOrWhiteSpace(t.text)).Select(t=>new AuditText{path=PathFor(t.transform),text=t.text,bound=t.GetComponent<UiLocalizedText>()?.IsBound??false}).ToArray();var small=game.Content.GetComponentInParent<Canvas>().GetComponentsInChildren<Button>().Where(b=>b.isActiveAndEnabled&&b.interactable).Where(b=>{var r=((RectTransform)b.transform).rect;return r.width<43.5f||r.height<43.5f;}).Select(b=>PathFor(b.transform)+" "+((RectTransform)b.transform).rect.size).ToArray();pages.Add(new AuditPage{language=language,route=route,texts=texts,smallButtons=small});if(capture&&(language=="de"||language=="en"||language=="fr"&&route=="challenges"||language=="pl"&&route=="seasons"))WorkshopTests.Capture(390,846,Output+"/"+route+"-"+language+".png");}
  [UnityTest]public IEnumerator FreshMiraAndNameFlow(){GameRuntime.SavePathOverride=Path.Combine(directory,"fresh-save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();PortraitGameView.Set(390,846);yield return null;yield return null;WorkshopTests.Capture(390,846,Output+"/fresh-mira-de.png");Assert.That(game.Writable,Is.True,game.Status.text);game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));yield return null;yield return null;WorkshopTests.Capture(390,846,Output+"/fresh-after-name-de.png");Assert.That(game.State.Retention.aiName,Is.EqualTo("AURA"));}
  [UnityTest]public IEnumerator SmallAndLargeLegacyViews(){Prepare();Assert.That(game.Writable,Is.True,game.Status.text);foreach(string lang in new[]{"de","en"})foreach(int width in new[]{320,430}){game.Act(s=>SettingsRules.Change(s,"language",lang));PortraitGameView.Set(width,width==320?694:932);foreach(string route in new[]{"models","challenges","seasons"}){game.Show(route);yield return null;yield return null;yield return new WaitForSecondsRealtime(.12f);WorkshopTests.Capture(width,Screen.height,Output+"/"+route+"-"+lang+"-"+width+".png");}}}
  [UnityTest]public IEnumerator InspectRealViewsAllLanguagesAndEveryItemSprite(){PortraitGameView.Set(390,846);game.Show("hardware");yield return Record("de","fresh-labor");game.GetComponent<GameMenu>().Open();yield return Record("de","menu");game.GetComponent<GameMenu>().Close();Prepare();Assert.That(game.Writable,Is.True,game.Status.text);result.items=ItemBalance.Items.Select((d,i)=>{var a=i<game.WorkshopPrefab.ItemSprites.Length?game.WorkshopPrefab.ItemSprites[i]:null;return new AuditItemArt{id=d.Id,present=a!=null,sprite=a!=null?a.name:"",texture=a!=null?a.texture.name:""};}).ToArray();Assert.That(result.items.Length,Is.EqualTo(36));Assert.That(result.items.All(a=>a.present),Is.True,"Every catalog item needs actual art");Assert.That(game.WorkshopPrefab.ItemSprites.Select(s=>s.GetInstanceID()).Distinct().Count(),Is.EqualTo(36),"Distinct sprite assignments, not one fallback for all items");
   foreach(string language in new[]{"de","en","es","fr","pt","it","pl"}){game.Act(s=>SettingsRules.Change(s,"language",language));Assert.That(game.State.Settings.language,Is.EqualTo(language));foreach(string route in new[]{"hardware","training","research","models","prestige","shop","market","gems","store","ads","missions","seasons","profile","company","progress","story","settings","storage","goals","production","challenges"}){game.Show(route);yield return Record(language,route);if(route=="prestige"){game.PrestigeView.SetLayer(true);yield return Record(language,"axioms");}}game.Show("items");foreach(string mode in new[]{"inventory","components","blueprints","craft","fusion"}){game.WorkshopView.ChangeMode(mode);yield return Record(language,"forge-"+mode);}game.Show("profile");foreach(string button in new[]{"ShowBadges","ShowAchievements","ShowOnboarding","ShowStaticChallenges"}){GameObject.Find(button).GetComponent<Button>().onClick.Invoke();yield return Record(language,button);}}
   Assert.That(pages.All(p=>p.texts.All(t=>t.bound||!t.text.Any(char.IsLetter))),Is.True,"Unbound labels: "+string.Join("; ",pages.SelectMany(p=>p.texts).Where(t=>!t.bound&&t.text.Any(char.IsLetter)).Take(6).Select(t=>t.path+"="+t.text)));Assert.That(pages.All(p=>p.texts.Length>0),Is.True,"Audit collector must observe actual canvas text");result.pages=pages.ToArray();File.WriteAllText(Output+"/audit.json",JsonUtility.ToJson(result,true));Assert.That(result.pages.Length,Is.EqualTo(219));
  }
 }
}
